use rk3588_boot_support::{DelayUs,Mmio32};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum LinkWaitError{Jitter{status:u32},Timeout{last:u32}}
pub fn wait_link_up<I:Mmio32+DelayUs>(io:&mut I,ctrl_base:u64,max_samples:u32)->Result<u32,LinkWaitError>{let mut transition=false;let mut last=0u32;let mut left=max_samples;while left>0{let s=io.read32(ctrl_base+768);last=s;match s&0x30000{0x30000=>return Ok(s),0x10000=>transition=true,_=>{if s==0&&transition{return Err(LinkWaitError::Jitter{status:s})}}}io.delay_us(10);left-=1}Err(LinkWaitError::Timeout{last})}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum HotResetWait{Observed,ForcedFromL2,Timeout}
pub fn wait_hot_reset_or_l2<I:Mmio32+DelayUs>(io:&mut I,ctrl_base:u64)->HotResetWait{io.delay_us(300);let mut left=3000u32;while left>0{if io.read32(ctrl_base+16)&4!=0{io.write32(ctrl_base+16,4);return HotResetWait::Observed}if io.read32(ctrl_base+4)&0x400!=0{io.write32(ctrl_base+16,4);return HotResetWait::ForcedFromL2}io.delay_us(100);left-=1}HotResetWait::Timeout}
#[cfg(test)]mod tests{use super::*;struct M{s:[u32;4],i:usize,hot:u32,l2:u32,w:u32}impl Mmio32 for M{fn read32(&mut self,a:u64)->u32{if a==768{let x=self.s[self.i.min(3)];self.i+=1;x}else if a==16{self.hot}else if a==4{self.l2}else{0}}fn write32(&mut self,a:u64,v:u32){if a==16{self.w=v}}}impl DelayUs for M{fn delay_us(&mut self,_:u32){}}#[test]fn link(){let mut m=M{s:[0,0x10000,0x10000,0x30000],i:0,hot:4,l2:0,w:0};assert_eq!(wait_link_up(&mut m,0,10),Ok(0x30000));assert_eq!(wait_hot_reset_or_l2(&mut m,0),HotResetWait::Observed);assert_eq!(m.w,4);}}
